public class GameBarrier {
    private static final int GAME_NOTREADY = 0;
    private static final int GAME_FILLING = 1;
    private static final int GAME_FILLED = 2;

    private Lock mutex;
    private int state;
    private Condition cv;

    /* Additional class variables */
    private int numWaiters;
    private int numPlayers;

    public GameBarrier(Lock lock) {
        this.mutex = lock;
        this.state = GAME_NOTREADY;
        this.cv = lock.newCondition();
        this.numWaiters = 0;
        this.numPlayers = 0;
    }

    public void waitToPlay() {
        mutex.acquire();

        numWaiters++;

        while ((state == GAME_FILLED) || (numPlayers == 4)) {
            try {
                cv.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        numWaiters--;
        numPlayers++;

        if (numPlayers == 4) {
            state = GAME_FILLED;
        }

        cv.signalAll();
        mutex.release();
    }

    public void donePlaying() {
        mutex.acquire();

        numPlayers--;

        if (numPlayers == 0) {
            state = (numWaiters >= 4) ? GAME_FILLING : GAME_NOTREADY;
            cv.signalAll();  // Wake up waiting players if ready
        }

        mutex.release();
    }
}
```

