import java.util.ArrayList;

public class Knapsack {
    protected ArrayList<String> itemNames;
    private ArrayList<Integer> itemWeights;
    private final int weightCapacity;
    private int totalWeight;

    public Knapsack(int weightCapacity) {
        if (weightCapacity < 0) {
            throw new IllegalStateException("Weight capacity cannot be negative.");
        }
        itemNames = new ArrayList<String>();
        itemWeights = new ArrayList<Integer>();
        this.weightCapacity = weightCapacity;
        this.totalWeight = 0;
    }

    public void addItem(String name, int weight) {
        if (weight < 0) {
            throw new IllegalStateException("Item weight cannot be negative.");
        }
        if (itemNames.contains(name)) {
            throw new IllegalStateException("An item with the same name already exists.");
        }
        if (totalWeight + weight > weightCapacity) {
            throw new IllegalStateException("Adding this item exceeds the knapsack's weight capacity.");
        }

        itemNames.add(name);
        itemWeights.add(weight);
        totalWeight += weight;  // Update the total weight
    }

    public void removeItem(String name) {
        int itemIndex = itemNames.indexOf(name);

        if (itemIndex == -1) {
            throw new IllegalStateException("Item not found in the knapsack.");
        }

        totalWeight -= itemWeights.get(itemIndex); // Deduct its weight from totalWeight

        itemNames.remove(itemIndex);
        itemWeights.remove(itemIndex);
    }

    public int getTotalWeight() {
        return totalWeight;
    }
}
```

